window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6168c019edf16c1c"]={"versions": [{"id": "FIG-6168c019edf16c1c", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Veranschaulichung der Modellierung von Variant-Datentypen im AUTOSAR-Adaptive-Platform-Manifest (Metamodellbereich Datentypen/ImplementationDataTypes). Das Diagramm illustriert ein konkretes Instanzmodell für eine typsichere Union (<code>std::variant</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf konkrete Metamodell-Instanzen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>MyVariant :CppImplementationDataType</code>: Übergeordneter Datentyp mit Attribut <code>category = VARIANT</code>.\n</li><li>Zwei anonyme Instanzen <code>:CppTemplateArgument</code>: Werden jeweils über eine Kompositionsbeziehung mit der Rollenbezeichnung <code>+templateArgument</code> von <code>MyVariant</code> aggregiert.\n</li><li><code>float : CppImplementationDataType</code>: Konkreter Typalternative-Wert mit Attribut <code>category = VALUE</code>.\n</li><li><code>uint8 : CppImplementationDataType</code>: Konkreter Typalternative-Wert mit Attribut <code>category = VALUE</code>.\n</li><li>Gerichtet assoziiert über Pfeile mit der Rollenbezeichnung <code>+templateType</code> referenziert jede <code>:CppTemplateArgument</code>-Instanz jeweils eine der beiden <code>:CppImplementationDataType</code>-Wertinstanzen (<code>float</code> bzw. <code>uint8</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturbeispiel eines Objektdiagramms; kein dynamischer Sequenz- oder Laufzeitablauf. Das Diagramm spezifiziert die statische Aggregations- und Referenzierungsstruktur bei der Definition der Typalternativen innerhalb einer Manifest-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>CppImplementationDataType</code> mit <code>category = VARIANT</code> repräsentiert eine C++-Union (<code>std::variant</code> oder anwenderspezifische Typen wie <code>my::variant</code>). Jede Alternative wird über ein aggregiertes <code>CppTemplateArgument</code> modelliert, dessen <code>+templateType</code> auf die konkrete Typdefinition verweist. Die ARXML-Reihenfolge der <code>templateArgument</code>-Elemente bestimmt die Reihenfolge der Typalternativen in der C++-Template-Signatur, ist im UML-Objektdiagramm selbst jedoch nicht explizit visualisiert. Die Aggregation eines Template-Arguments mit Allokator-Rolle (<code>allocator</code>) ist gemäß Metamodell-Constraint unzulässig.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b0cfbe78e2bb785e", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Veranschaulichung der Modellierung von Variant-Datentypen im AUTOSAR-Adaptive-Platform-Manifest (Metamodellbereich Datentypen/StdCppImplementationDataType). Das Diagramm illustriert ein konkretes Instanzmodell für eine C++-Standardbibliotheks-Variant-Definition.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf Metamodell-Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>MyVariant: StdCppImplementationDataType</code>: Übergeordneter Datentyp mit Attribut <code>category = VARIANT</code>.\n</li><li>Zwei anonyme Instanzen <code>:CppTemplateArgument</code>: Werden über Kompositionen mit der Rollenbezeichnung <code>+templateArgument</code> von <code>MyVariant</code> aggregiert.\n</li><li><code>float: StdCppImplementationDataType</code>: Typalternative mit Attribut <code>category = VALUE</code>.\n</li><li><code>uint8_t: StdCppImplementationDataType</code>: Typalternative mit Attribut <code>category = VALUE</code>.\n</li><li>Gerichtet referenziert über Pfeile mit der Rollenbezeichnung <code>+templateType</code> verbindet jedes <code>:CppTemplateArgument</code> das Aggregat mit der jeweiligen Zieltyp-Instanz (<code>float</code> bzw. <code>uint8_t</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturbeispiel eines Objektdiagramms; kein dynamischer Sequenz- oder Laufzeitablauf. Das Diagramm spezifiziert die statische Aggregations- und Referenzierungsstruktur bei der Definition der Typalternativen innerhalb einer Manifest-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>StdCppImplementationDataType</code> mit <code>category = VARIANT</code> modelliert Datentyp-Alternativen auf Basis von Standard-C++-Typen. Jede Alternative wird durch ein aggregiertes <code>CppTemplateArgument</code> definiert, welches über die Relation <code>+templateType</code> auf einen entsprechenden <code>StdCppImplementationDataType</code> (wie <code>float</code> oder <code>uint8_t</code>) verweist. Die Serialisierungsreihenfolge in ARXML ist bindend für die Template-Parameterabfolge des generierten C++-Typs.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4b441181374cb534", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Veranschaulichung der Modellierung von Variant-Datentypen im AUTOSAR-Adaptive-Platform-Manifest (Metamodellbereich Datentypen/StdCppImplementationDataType). Das Diagramm illustriert ein konkretes Instanzmodell für eine C++-Standardbibliotheks-Variant-Definition.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf Metamodell-Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>MyVariant: StdCppImplementationDataType</code>: Übergeordneter Datentyp mit Attribut <code>category = VARIANT</code>.\n</li><li>Zwei anonyme Instanzen <code>:CppTemplateArgument</code>: Werden über Kompositionen mit der Rollenbezeichnung <code>+templateArgument</code> von <code>MyVariant</code> aggregiert.\n</li><li><code>float: StdCppImplementationDataType</code>: Typalternative mit Attribut <code>category = VALUE</code>.\n</li><li><code>uint8_t: StdCppImplementationDataType</code>: Typalternative mit Attribut <code>category = VALUE</code>.\n</li><li>Gerichtet referenziert über Pfeile mit der Rollenbezeichnung <code>+templateType</code> verbindet jedes <code>:CppTemplateArgument</code> das Aggregat mit der jeweiligen Zieltyp-Instanz (<code>float</code> bzw. <code>uint8_t</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturbeispiel eines Objektdiagramms; kein dynamischer Sequenz- oder Laufzeitablauf. Das Diagramm spezifiziert die statische Aggregations- und Referenzierungsstruktur bei der Definition der Typalternativen innerhalb einer Manifest-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>StdCppImplementationDataType</code> mit <code>category = VARIANT</code> modelliert Datentyp-Alternativen auf Basis von Standard-C++-Typen. Jede Alternative wird durch ein aggregiertes <code>CppTemplateArgument</code> definiert, welches über die Relation <code>+templateType</code> auf einen entsprechenden <code>StdCppImplementationDataType</code> (wie <code>float</code> oder <code>uint8_t</code>) verweist. Die Serialisierungsreihenfolge in ARXML ist bindend für die Template-Parameterabfolge des generierten C++-Typs.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-022e82c24471b58c", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Veranschaulichung der Modellierung von Variant-Datentypen im AUTOSAR-Adaptive-Platform-Manifest (Metamodellbereich Datentypen/StdCppImplementationDataType). Das Diagramm illustriert ein konkretes Instanzmodell für eine C++-Standardbibliotheks-Variant-Definition.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf Metamodell-Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>MyVariant: StdCppImplementationDataType</code>: Übergeordneter Datentyp mit Attribut <code>category = VARIANT</code>.\n</li><li>Zwei anonyme Instanzen <code>:CppTemplateArgument</code>: Werden über Kompositionen mit der Rollenbezeichnung <code>+templateArgument</code> von <code>MyVariant</code> aggregiert.\n</li><li><code>float: StdCppImplementationDataType</code>: Typalternative mit Attribut <code>category = VALUE</code>.\n</li><li><code>uint8_t: StdCppImplementationDataType</code>: Typalternative mit Attribut <code>category = VALUE</code>.\n</li><li>Gerichtet referenziert über Pfeile mit der Rollenbezeichnung <code>+templateType</code> verbindet jedes <code>:CppTemplateArgument</code> das Aggregat mit der jeweiligen Zieltyp-Instanz (<code>float</code> bzw. <code>uint8_t</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturbeispiel eines Objektdiagramms; kein dynamischer Sequenz- oder Laufzeitablauf. Das Diagramm spezifiziert die statische Aggregations- und Referenzierungsstruktur bei der Definition der Typalternativen innerhalb einer Manifest-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>StdCppImplementationDataType</code> mit <code>category = VARIANT</code> modelliert Datentyp-Alternativen auf Basis von Standard-C++-Typen. Jede Alternative wird durch ein aggregiertes <code>CppTemplateArgument</code> definiert, welches über die Relation <code>+templateType</code> auf einen entsprechenden <code>StdCppImplementationDataType</code> (wie <code>float</code> oder <code>uint8_t</code>) verweist. Die Serialisierungsreihenfolge in ARXML ist bindend für die Template-Parameterabfolge des generierten C++-Typs.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2a0952147b52f979", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Veranschaulichung der Modellierung von Variant-Datentypen im AUTOSAR-Adaptive-Platform-Manifest (Metamodellbereich Datentypen/StdCppImplementationDataType). Das Diagramm illustriert ein konkretes Instanzmodell für eine C++-Standardbibliotheks-Variant-Definition.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf Metamodell-Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>MyVariant: StdCppImplementationDataType</code>: Übergeordneter Datentyp mit Attribut <code>category = VARIANT</code>.\n</li><li>Zwei anonyme Instanzen <code>:CppTemplateArgument</code>: Werden über Kompositionen mit der Rollenbezeichnung <code>+templateArgument</code> von <code>MyVariant</code> aggregiert.\n</li><li><code>float: StdCppImplementationDataType</code>: Typalternative mit Attribut <code>category = VALUE</code>.\n</li><li><code>uint8_t: StdCppImplementationDataType</code>: Typalternative mit Attribut <code>category = VALUE</code>.\n</li><li>Gerichtet referenziert über Pfeile mit der Rollenbezeichnung <code>+templateType</code> verbindet jedes <code>:CppTemplateArgument</code> das Aggregat mit der jeweiligen Zieltyp-Instanz (<code>float</code> bzw. <code>uint8_t</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturbeispiel eines Objektdiagramms; kein dynamischer Sequenz- oder Laufzeitablauf. Das Diagramm spezifiziert die statische Aggregations- und Referenzierungsstruktur bei der Definition der Typalternativen innerhalb einer Manifest-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>StdCppImplementationDataType</code> mit <code>category = VARIANT</code> modelliert Datentyp-Alternativen auf Basis von Standard-C++-Typen. Jede Alternative wird durch ein aggregiertes <code>CppTemplateArgument</code> definiert, welches über die Relation <code>+templateType</code> auf einen entsprechenden <code>StdCppImplementationDataType</code> (wie <code>float</code> oder <code>uint8_t</code>) verweist. Die Serialisierungsreihenfolge in ARXML ist bindend für die Template-Parameterabfolge des generierten C++-Typs.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6168c019edf16c1c", "to": "FIG-b0cfbe78e2bb785e", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklasse von <code>MyVariant</code>, <code>float</code> und <code>uint8</code> von <code>CppImplementationDataType</code> zu <code>StdCppImplementationDataType</code> geändert.\n</li><li>Instanzbezeichnung des ganzzahligen Basistyps von <code>uint8</code> auf <code>uint8_t</code> geändert.\n</li><li>Typografischer Leerraum vor den Doppelpunkten in den Objektbezeichnungen entfernt (<code>float :</code> zu <code>float:</code>, <code>uint8 :</code> zu <code>uint8_t:</code>).\n</li></ul>"}, {"from": "FIG-b0cfbe78e2bb785e", "to": "FIG-4b441181374cb534", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4b441181374cb534", "to": "FIG-022e82c24471b58c", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-022e82c24471b58c", "to": "FIG-2a0952147b52f979", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
